1: // ---- clawflow v0.2 --------------------------------------------------------------
2: // Declarative agentic workflow format.
3: // Designed to be written by LLMs, run anywhere.
4: //
5: // Runtime targets:
6: //   - OpenClaw plugin (this package)
7: //   - Cloudflare Workers (via transpiler -- see transpile.ts)
8: //   - Standalone Node.js server (future)
9: 
10: // ---- Flow Definition ------------------------------------------------------------
11: 
12: export interface FlowDefinition {
13:   flow: string; // unique name, e.g. "triage-support-ticket"
14:   version?: string; // semver, e.g. "1.0.0"
15:   description?: string;
16:   /**
17:    * Declared inputs the flow expects. Optional: when omitted, the flow accepts
18:    * any payload (anything-goes mode). When present, required inputs must be
19:    * supplied at runtime or the flow fails before any node executes. Extra
20:    * undeclared keys in the payload pass through and are reachable via
21:    * {{ inputs.* }} but are not statically checked.
22:    */
23:   inputs?: Record<string, InputSpec>;
24:   /** Environment variables the flow expects. Values are defaults; null means required (runtime must provide). */
25:   env?: Record<string, string | null>;
26:   nodes: FlowNode[];
27: }
28: 
29: export interface InputSpec {
30:   type?: "string" | "number" | "boolean" | "object" | "array";
31:   required?: boolean;
32:   description?: string;
33:   default?: unknown;
34: }
35: 
36: // ---- Retry Policy ---------------------------------------------------------------
37: // Applies to any node. Learned from Cloudflare WorkflowStepConfig.
38: 
39: export interface RetryPolicy {
40:   limit: number; // max attempts (default: 1 = no retry)
41:   delay: string | number; // e.g. "2s", "1m", or milliseconds
42:   backoff?: "linear" | "exponential" | "constant";
43: }
44: 
45: // ---- Node Union -----------------------------------------------------------------
46: 
47: export type FlowNode =
48:   | AiNode
49:   | AgentNode
50:   | BranchNode
51:   | ConditionNode
52:   | LoopNode
53:   | ParallelNode
54:   | HttpNode
55:   | MemoryNode
56:   | WaitNode
57:   | SleepNode
58:   | CodeNode
59:   | ExecNode;
60: 
61: export interface BaseNode {
62:   name: string;
63:   do: string;
64:   output?: string; // store result under this key in flow state
65:   retry?: RetryPolicy; // per-node retry policy
66:   timeout?: string | number; // e.g. "30s", or ms integer
67: }
68: 
69: // ---- Field resolution modes -----------------------------------------------------
70: // Single source of truth for how each node field is treated when a flow runs.
71: // Both the runner (template interpolation) and the validator (template-ref checks)
72: // read the per-node `*_FIELD_MODES` maps below, so "which fields are dynamic" is
73: // declared once — not re-decided in every exec handler and again in the validator.
74: export type FieldMode =
75:   // A string interpolated with {{ }} templates at exec time (resolveTemplate).
76:   | "template"
77:   // An array of template strings, or a map of string values. Each element is resolved.
78:   | "templateEach"
79:   // A string-or-object deep-resolved, type-preserving (resolveBodyObject). The owning
80:   // handler performs this resolution; the generic pass leaves the field untouched.
81:   | "templateDeep"
82:   // A raw dotted state path read via getPath (never {{ }}-interpolated).
83:   | "path"
84:   // A JS expression evaluated against state (condition `if`).
85:   | "expr"
86:   // A FlowNode[] sub-block, resolved lazily as it executes (loop/branch/condition/parallel).
87:   | "children"
88:   // Executable source, passed through untouched and run (code `run`).
89:   | "code"
90:   // Passed through untouched: enums, numbers, output shapes, tool lists.
91:   | "literal";
92: 
93: // A field-mode map must list EXACTLY the own keys of T (minus BaseNode). Adding a
94: // field to an interface without classifying it — or classifying one that doesn't
95: // exist — is a compile error. This is what stops a new value field from silently
96: // shipping without interpolation (the agentId/session class of bug).
97: type OwnKeys<T extends BaseNode> = Exclude<keyof T, keyof BaseNode>;
98: type FieldModeMap<T extends BaseNode> = Record<OwnKeys<T>, FieldMode>;
99: 
100: // ---- Node Types -----------------------------------------------------------------
101: 
102: export interface AiNode extends BaseNode {
103:   do: "ai";
104:   prompt: string;
105:   input?: string; // dotted path into flow state
106:   schema?: Record<string, string>; // output shape; enables JSON mode
107:   model?: "fast" | "smart" | "best" | string;
108:   /**
109:    * Named backend to run this node against — a key in `PluginConfig.providers`
110:    * or a built-in (`"openrouter"`, `"anthropic"`, `"openai"`). Falls back to
111:    * `PluginConfig.defaultProvider`, then to legacy env-var auto-detection.
112:    */
113:   provider?: string;
114:   temperature?: number;
115:   maxTokens?: number;
116:   /** File paths (images, PDFs) to include as multimodal content. Supports templates. */
117:   attachments?: string[];
118: }
119: const AI_FIELD_MODES: FieldModeMap<AiNode> = {
120:   prompt: "template",
121:   input: "path",
122:   schema: "literal",
123:   model: "literal",
124:   provider: "literal",
125:   temperature: "literal",
126:   maxTokens: "literal",
127:   attachments: "templateEach",
128: };
129: 
130: export interface AgentNode extends BaseNode {
131:   do: "agent";
132:   task: string;
133:   input?: string;
134:   tools?: string[];
135:   // Field names mirror `openclaw agent`'s flags 1:1 (agent→--agent, sessionKey→
136:   // --session-key, sessionId→--session-id, channel→--channel). `agentId`/`session`
137:   // are the pre-1.3.1 names, kept as deprecated aliases (the new name wins if both set).
138:   /**
139:    * OpenClaw agent slug to delegate to (e.g. "main", "clawflow"), mapped to
140:    * `openclaw agent --agent`. A plain slug, never a session key. Defaults to
141:    * "main" if no target (`agent`/`sessionKey`/`sessionId`) is set.
142:    */
143:   agent?: string;
144:   /** @deprecated Renamed to `agent` (aligns with `--agent`). Still accepted; `agent` wins if both are set. */
145:   agentId?: string;
146:   /**
147:    * OpenClaw session key to target, mapped to `openclaw agent --session-key`.
148:    * Use this to run inside a specific existing session — a channel, a named
149:    * agent session — rather than a fresh turn. "agent:"-prefixed keys (e.g.
150:    * "agent:main:slack:channel:agent") are self-scoping; a bare key (e.g.
151:    * "incident-42") is scoped by `agent` (or the default agent). May be
152:    * combined with `agent` — OpenClaw requires them to be consistent.
153:    */
154:   sessionKey?: string;
155:   /** @deprecated Renamed to `sessionKey` (aligns with `--session-key`). Still accepted; `sessionKey` wins if both are set. */
156:   session?: string;
157:   /**
158:    * Explicit OpenClaw session id, mapped to `openclaw agent --session-id`. The
159:    * most specific target: it names one session directly (scoped by `agent`).
160:    * Prefer `sessionKey` for channel/self-scoping keys; use this to resume a known id.
161:    */
162:   sessionId?: string;
163:   /**
164:    * Delivery channel for the agent's reply, mapped to `openclaw agent --channel`
165:    * (e.g. "slack", "telegram", "whatsapp"). Omit to use the session's own channel.
166:    */
167:   channel?: string;
168: }
169: const AGENT_FIELD_MODES: FieldModeMap<AgentNode> = {
170:   task: "template",
171:   input: "path",
172:   tools: "literal",
173:   // Selector fields map to CLI flags and are interpolated so a value computed by a
174:   // prior node (e.g. "{{ route.agent_slug }}") can target the delegate/reply channel.
175:   agent: "template",
176:   agentId: "template", // deprecated alias for `agent`
177:   sessionKey: "template",
178:   session: "template", // deprecated alias for `sessionKey`
179:   sessionId: "template",
180:   channel: "template",
181: };
182: 
183: export interface BranchNode extends BaseNode {
184:   do: "branch";
185:   on: string; // dotted path in flow state
186:   paths: Record<string, FlowNode[]>; // value -> sub-flow to execute
187:   default?: FlowNode[]; // sub-flow if no path matches
188: }
189: const BRANCH_FIELD_MODES: FieldModeMap<BranchNode> = {
190:   on: "path",
191:   paths: "children",
192:   default: "children",
193: };
194: 
195: export interface LoopNode extends BaseNode {
196:   do: "loop";
197:   over: string; // dotted path to array
198:   as: string; // variable name for current item
199:   nodes: FlowNode[];
200: }
201: const LOOP_FIELD_MODES: FieldModeMap<LoopNode> = {
202:   over: "path",
203:   as: "literal",
204:   nodes: "children",
205: };
206: 
207: export interface ParallelNode extends BaseNode {
208:   do: "parallel";
209:   nodes: FlowNode[];
210:   mode?: "all" | "race"; // "all" = wait for all, "race" = first wins
211: }
212: const PARALLEL_FIELD_MODES: FieldModeMap<ParallelNode> = {
213:   nodes: "children",
214:   mode: "literal",
215: };
216: 
217: export interface HttpNode extends BaseNode {
218:   do: "http";
219:   url: string;
220:   method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
221:   body?: string | Record<string, unknown>;
222:   headers?: Record<string, string>;
223: }
224: const HTTP_FIELD_MODES: FieldModeMap<HttpNode> = {
225:   url: "template",
226:   method: "literal",
227:   body: "templateDeep",
228:   headers: "templateEach",
229: };
230: 
231: export interface MemoryNode extends BaseNode {
232:   do: "memory";
233:   action: "read" | "write" | "delete";
234:   key: string;
235:   value?: string; // required for write
236: }
237: const MEMORY_FIELD_MODES: FieldModeMap<MemoryNode> = {
238:   action: "literal",
239:   key: "template",
240:   value: "template",
241: };
242: 
243: /**
244:  * wait — pause for human approval or external event.
245:  *
246:  * for: "approval" — human-in-the-loop gate with token-based resume.
247:  *   Registers a pending approval, provides a token for resume.
248:  *   On approval: output = { approved: true, approvedAt: string, token: string }
249:  *   On denial: flow is cancelled.
250:  *
251:  * for: "event" — wait for an external event (webhook, signal).
252:  *
253:  * Example:
254:  *   - name: review-pdfs
255:  *     do: wait
256:  *     for: approval
257:  *     prompt: "Review generated PDFs for {{ parsed.client_name }}"
258:  *     preview: "process_sheets[*].pdfPath"
259:  *     timeout: "24h"
260:  *     output: approval
261:  */
262: export interface WaitNode extends BaseNode {
263:   do: "wait";
264:   for: "approval" | "event";
265:   prompt?: string; // shown for approval gates (supports templates)
266:   preview?: string; // dotted path or wildcard to data shown alongside prompt (for: approval)
267:   event?: string; // event type to match (for: event)
268:   timeout?: string; // e.g. "24h", "5m" -- fail if exceeded
269: }
270: const WAIT_FIELD_MODES: FieldModeMap<WaitNode> = {
271:   for: "literal",
272:   prompt: "template",
273:   preview: "templateDeep",
274:   event: "literal",
275: };
276: 
277: export interface SleepNode extends BaseNode {
278:   do: "sleep";
279:   duration: string; // e.g. "30s", "5m", "2h", "1d"
280: }
281: const SLEEP_FIELD_MODES: FieldModeMap<SleepNode> = {
282:   duration: "literal",
283: };
284: 
285: export interface CodeNode extends BaseNode {
286:   do: "code";
287:   run: string;
288:   input?: string;
289: }
290: const CODE_FIELD_MODES: FieldModeMap<CodeNode> = {
291:   run: "code",
292:   input: "path",
293: };
294: 
295: /**
296:  * exec — run a shell command deterministically, no AI involved.
297:  * Templates in `command` are resolved before execution.
298:  * Output: { stdout: string, stderr: string, exitCode: number }
299:  *
300:  * Example:
301:  *   - name: build-pdf
302:  *     do: exec
303:  *     command: "python3 /path/fill_foglio.py '{{ pdfPath }}' '{{ sheet | json }}'"
304:  *     output: buildResult
305:  */
306: export interface ExecNode extends BaseNode {
307:   do: "exec";
308:   command: string;
309:   cwd?: string; // working directory (resolved via templates)
310: }
311: const EXEC_FIELD_MODES: FieldModeMap<ExecNode> = {
312:   command: "template",
313:   cwd: "template",
314: };
315: 
316: /**
317:  * condition — if/else with sub-node blocks that reconverge.
318:  * Like branch, condition runs inline sub-nodes and merges back into
319:  * the main flow. Use condition for boolean logic, branch for multi-way
320:  * value matching.
321:  *
322:  * The `if` field is a JS expression evaluated against flow state.
323:  * Dotted paths like "order.status" resolve from state.
324:  * Comparison operators: ==, !=, >, <, >=, <=
325:  * Logical operators: &&, ||, !
326:  *
327:  * Example:
328:  *   - name: check-transport
329:  *     do: condition
330:  *     if: "extractOrder.transport_type == 'CLIENTE'"
331:  *     then:
332:  *       - name: pickup-note
333:  *         do: code
334:  *         run: "'Client picks up'"
335:  *         output: note
336:  *     else:
337:  *       - name: delivery-note
338:  *         do: code
339:  *         run: "'We deliver'"
340:  *         output: note
341:  *     output: condition_result
342:  */
343: export interface ConditionNode extends BaseNode {
344:   do: "condition";
345:   if: string; // JS expression evaluated against flow state
346:   then: FlowNode[]; // nodes to run when condition is true
347:   else?: FlowNode[]; // nodes to run when condition is false
348: }
349: const CONDITION_FIELD_MODES: FieldModeMap<ConditionNode> = {
350:   if: "expr",
351:   then: "children",
352:   else: "children",
353: };
354: 
355: // ---- Field-mode registry (the single source of truth) ---------------------------
356: // Maps each built-in node type to its per-field resolution modes. The runner reads
357: // this to interpolate the right fields; the validator reads it to know which fields
358: // carry {{ }} templates. Add a node type here and both consumers pick it up.
359: 
360: export const NODE_FIELD_MODES: Record<string, Record<string, FieldMode>> = {
361:   ai:        AI_FIELD_MODES,
362:   agent:     AGENT_FIELD_MODES,
363:   branch:    BRANCH_FIELD_MODES,
364:   condition: CONDITION_FIELD_MODES,
365:   loop:      LOOP_FIELD_MODES,
366:   parallel:  PARALLEL_FIELD_MODES,
367:   http:      HTTP_FIELD_MODES,
368:   memory:    MEMORY_FIELD_MODES,
369:   wait:      WAIT_FIELD_MODES,
370:   sleep:     SLEEP_FIELD_MODES,
371:   code:      CODE_FIELD_MODES,
372:   exec:      EXEC_FIELD_MODES,
373: };
374: 
375: // ---- Allowed Node Keys (derived from the field-mode registry) -------------------
376: // Used by the validator to reject unknown fields. Own keys come straight from each
377: // node's field-mode map, so the allow-list can never drift from the classification.
378: 
379: const BASE_KEYS: readonly string[] = ["name", "do", "output", "retry", "timeout"];
380: 
381: export const NODE_KEYS: Record<string, ReadonlySet<string>> = Object.fromEntries(
382:   Object.entries(NODE_FIELD_MODES).map(([type, modes]) => [
383:     type,
384:     new Set([...BASE_KEYS, ...Object.keys(modes)]),
385:   ]),
386: );
387: 
388: // ---- Runtime Types --------------------------------------------------------------
389: 
390: export interface FlowState {
391:   inputs?: unknown;
392:   [key: string]: unknown;
393: }
394: 
395: // Vocabulary aligned with Cloudflare InstanceStatus for future portability
396: export type NodeStatus =
397:   | "queued"
398:   | "running"
399:   | "ok"
400:   | "retrying"
401:   | "error"
402:   | "skipped"
403:   | "waiting"
404:   | "paused";
405: 
406: export interface TraceEntry {
407:   node: string;
408:   do: string;
409:   status: NodeStatus;
410:   attempt?: number; // which retry attempt (1-based)
411:   output?: unknown;
412:   error?: string;
413:   durationMs: number;
414: }
415: 
416: export type FlowStatus =
417:   | "running"
418:   | "completed"
419:   | "paused"
420:   | "waiting"
421:   | "failed"
422:   | "cancelled";
423: 
424: export interface FlowResult {
425:   ok: boolean;
426:   status: FlowStatus;
427:   flowName: string;
428:   instanceId: string; // stable ID for this run
429:   state: FlowState;
430:   trace: TraceEntry[];
431:   // Set when status = "paused" (approval/approve) or "waiting" (event)
432:   pausedAt?: string;
433:   resumeToken?: string;
434:   waitingFor?: {
435:     type: "approval" | "event";
436:     event?: string; // event type name if waiting for event
437:     prompt?: string;
438:     preview?: unknown; // resolved preview data for approve nodes
439:     timeout?: string;
440:   };
441:   error?: string;
442: }
443: 
444: // ---- Pending Approval -----------------------------------------------------------
445: 
446: export interface PendingApproval {
447:   token: string; // short random token for resume
448:   instanceId: string;
449:   flowName: string;
450:   node: string; // approve node name
451:   prompt: string; // resolved prompt text
452:   preview?: unknown; // resolved preview data
453:   createdAt: string;
454:   expiresAt: string;
455: }
456: 
457: // ---- Inference Function ---------------------------------------------------------
458: // Pluggable AI completion function. When running inside OpenClaw, the plugin
459: // injects a function that calls the gateway's OpenAI-compatible endpoint,
460: // reusing whatever providers/keys are already configured.
461: 
462: /** A single content part in a multimodal message (OpenAI/OpenRouter-compatible format). */
463: export type ContentPart =
464:   | { type: "text"; text: string }
465:   | { type: "image_url"; image_url: { url: string } }
466:   | { type: "file"; file: { filename: string; file_data: string } };
467: 
468: export interface InferenceRequest {
469:   model: string;
470:   system: string;
471:   prompt: string;
472:   /** When set, the prompt is multimodal — providers should use this instead of `prompt`. */
473:   content?: ContentPart[];
474:   temperature?: number;
475:   maxTokens?: number;
476: }
477: 
478: export interface InferenceResult {
479:   text: string;
480: }
481: 
482: export type InferenceFn = (req: InferenceRequest) => Promise<InferenceResult>;
483: 
484: // ---- Providers ------------------------------------------------------------------
485: // A named AI backend an `ai` node can target. When the host resolves per-caller
486: // credentials (e.g. an org's BYOK key behind a gateway), point a provider at that
487: // endpoint so flow AI spend follows the same credential/routing path as the rest
488: // of the platform instead of a shared process-env key.
489: 
490: export interface ProviderSpec {
491:   /** Base URL of the provider, e.g. "https://api.clawnify.com/v1". */
492:   baseUrl: string;
493:   /** Wire format. Default "openai-completions". */
494:   api?: "openai-completions" | "anthropic-messages";
495:   /** Literal API key. Prefer `apiKeyEnv` so secrets stay out of the config file. */
496:   apiKey?: string;
497:   /** Name of an env var holding the API key, resolved at call time. */
498:   apiKeyEnv?: string;
499:   /**
500:    * Maps flow model tiers ("fast" | "smart" | "best") to this provider's model
501:    * IDs. An `ai` node's `model` that isn't a tier and isn't one of these IDs is
502:    * normalized to the "smart" tier.
503:    */
504:   models?: Record<string, string>;
505: }
506: 
507: // ---- Plugin Config --------------------------------------------------------------
508: 
509: export interface ServeConfig {
510:   port: number;
511:   path?: string; // base path prefix, default "/flows"
512:   flowsDir?: string; // directory containing .json flow files, default workspace/flows
513: }
514: 
515: export interface PluginConfig {
516:   apiKey?: string;
517:   defaultModel?: string;
518:   baseUrl?: string;
519:   /**
520:    * Named AI backends selectable per `ai` node via its `provider` field. The
521:    * keys `"openrouter"`, `"anthropic"`, and `"openai"` are built in (env-keyed)
522:    * and can be overridden here.
523:    */
524:   providers?: Record<string, ProviderSpec>;
525:   /**
526:    * Provider used by `ai` nodes that don't set their own `provider`. When set,
527:    * it takes precedence over legacy env-var auto-detection, so a stray
528:    * `OPENROUTER_API_KEY` in the environment can't silently win.
529:    */
530:   defaultProvider?: string;
531:   memoryDir?: string;
532:   maxNodeDurationMs?: number;
533:   stateDir?: string; // where to persist flow state across restarts
534:   /** Override for AI inference — used by tests and embedders */
535:   inferenceFn?: InferenceFn;
536:   /** OpenClaw agent ID for do:agent nodes (e.g. "ops"). Falls back to --local if unset. */
537:   defaultAgent?: string;
538:   /** Optional HTTP server config — exposes a generic run endpoint per flow. */
539:   serve?: ServeConfig;
540:   /**
541:    * Optional custom step registry. Defaults to the module-level singleton
542:    * populated by `registerStepType()`. Provide a private registry for
543:    * test isolation or to run multiple FlowRunners with different step sets.
544:    */
545:   customSteps?: import("./custom-steps.js").StepRegistry;
546:   /**
547:    * Approval gate for the `flow_run` tool. Flows can call HTTP, exec, and
548:    * agent tools, so by default the plugin prompts the user before each run.
549:    * Hosts that need unattended automation can disable the gate entirely or
550:    * skip it for specific session contexts.
551:    */
552:   approval?: ApprovalConfig;
553: }
554: 
555: export interface ApprovalConfig {
556:   /** Disable the approval gate entirely. Default: `true` (gate enabled). */
557:   enabled?: boolean;
558:   /**
559:    * Substrings matched against the current session key. If any substring
560:    * appears in the session key, the approval gate is skipped for that run.
561:    * Useful for hook-driven sessions where no interactive channel is bound
562:    * (e.g. inbound email automation, where the session key looks like
563:    * `agent:main:main:email:<message-id>`). Default: `[]`.
564:    */
565:   skipSessionPatterns?: string[];
566:   /** Override the prompt timeout (ms). Default: `300000` (5 min). */
567:   timeoutMs?: number;
568:   /** Action on prompt timeout: `"allow"` or `"deny"`. Default: `"deny"`. */
569:   timeoutBehavior?: "allow" | "deny";
570:   /**
571:    * Gate flow-authoring tools (`flow_create` / `flow_edit` / `flow_publish` /
572:    * `flow_delete`) behind approval, independently of `enabled` (which governs
573:    * `flow_run`). Creating, editing, publishing, or deleting a flow definition
574:    * is a write action that should never happen unattended, so this applies on
575:    * every call and does NOT honor `skipSessionPatterns`. Default: `true`.
576:    */
577:   gateMutations?: boolean;
578: }
579: 
580: // ---- Model Shorthands -----------------------------------------------------------
581: 
582: export const MODEL_MAP: Record<string, string> = {
583:   fast: "google/gemini-3-flash-preview",
584:   smart: "anthropic/claude-sonnet-4.6",
585:   best: "minimax/minimax-m2.5",
586: };
587: export const DEFAULT_MODEL = "anthropic/claude-sonnet-4.6";
