590: // Maps both shorthand aliases and resolved model IDs.
591: export const OPENROUTER_MODEL_MAP: Record<string, string> = {
592:   fast: "google/gemini-3-flash-preview",
593:   smart: "anthropic/claude-sonnet-4.6",
594:   best: "minimax/minimax-m2.5",
595:   "google/gemini-3-flash-preview": "google/gemini-3-flash-preview",
596:   "anthropic/claude-sonnet-4.6": "anthropic/claude-sonnet-4.6",
597:   "minimax/minimax-m2.5": "minimax/minimax-m2.5",
598: };
