365: /** Extract template references {{ key.path }} from all string fields of a node */
366: function checkTemplateRefs(
367:   node: FlowNode,
368:   available: Set<string>,
369:   errors: ValidationError[],
370:   registry: StepRegistry,
371: ): void {
372:   const strings = collectStringFields(node, registry);
373:   // Simple path + optional filter
374:   const templatePattern = /\{\{\s*([\w.]+)\s*(?:\|\s*\w+)?\s*\}\}/g;
375:   // Wildcard: {{ path[*].field }}
376:   const wildcardPattern = /\{\{\s*([\w.]+)\[\*\](?:\.([\w.]+))?\s*\}\}/g;
377:   // Ternary: {{ expr ? val : val }} — extract dotted paths from condition
378:   const ternaryPattern = /\{\{\s*(.+?)\s*\?\s*(.+?)\s*:\s*(.+?)\s*\}\}/g;
379: 
380:   const checkRoot = (ref: string, field: string) => {
381:     const rootKey = ref.split(".")[0];
382:     if (!available.has(rootKey)) {
383:       errors.push({
384:         node: node.name,
385:         field,
386:         message: `Template "{{ ${ref} }}" references "${rootKey}" which is not an available output key. Available: ${[...available].sort().join(", ")}`,
387:       });
388:     }
389:   };
390: 
391:   for (const { field, value } of strings) {
392:     let remaining = value;
393:     let match;
394: 
395:     // Check ternaries and remove them from remaining
396:     while ((match = ternaryPattern.exec(value)) !== null) {
397:       // Extract paths from condition part, stripping string literals first
398:       const condCleaned = match[1].replace(/'[^']*'|"[^"]*"/g, "");
399:       const condPaths = condCleaned.match(/[\w.]+/g) ?? [];
400:       for (const p of condPaths) {
401:         if (/^\d/.test(p) || /^(true|false|null|undefined)$/.test(p)) continue;
402:         checkRoot(p, field);
403:       }
404:       remaining = remaining.replace(match[0], "");
405:     }
406: 
407:     // Check wildcards and remove them from remaining
408:     wildcardPattern.lastIndex = 0;
409:     while ((match = wildcardPattern.exec(remaining)) !== null) {
410:       checkRoot(match[1], field);
411:     }
412:     remaining = remaining.replace(wildcardPattern, "");
413: 
414:     // Check simple paths on what's left
415:     templatePattern.lastIndex = 0;
416:     while ((match = templatePattern.exec(remaining)) !== null) {
417:       checkRoot(match[1], field);
418:     }
419:   }
420: }
