487:   node: FlowNode,
488:   available: Set<string>,
489:   errors: ValidationError[],
490:   registry: StepRegistry,
491: ): void {
492:   switch (node.do) {
493:     case "branch": {
494:       const n = node as BranchNode;
495:       for (const nodes of Object.values(n.paths)) {
496:         validateNodes(nodes, available, errors, registry);
497:       }
498:       if (n.default) {
499:         validateNodes(n.default, available, errors, registry);
