529: /**
530:  * Collect all template-bearing string fields from a node (for {{ }} ref checking).
531:  *
532:  * Which fields carry templates comes from NODE_FIELD_MODES — the same registry the
533:  * runner interpolates against — so the validator can never disagree with runtime
534:  * about whether a field is dynamic (e.g. agent `agentId`/`session`). Modes template,
535:  * templateEach, and templateDeep are scanned; path/expr are checked separately by
536:  * checkStateRefs; children/code/literal carry no templates.
537:  */
538: function collectStringFields(
539:   node: FlowNode,
540:   registry: StepRegistry,
541: ): { field: string; value: string }[] {
542:   const result: { field: string; value: string }[] = [];
543:   const raw = node as unknown as Record<string, unknown>;
544: 
545:   const scan = (field: string, val: unknown) => {
546:     if (typeof val === "string") {
547:       result.push({ field, value: val });
548:     } else if (Array.isArray(val)) {
549:       val.forEach((v, i) => {
550:         if (typeof v === "string") result.push({ field: `${field}[${i}]`, value: v });
551:       });
552:     } else if (val !== null && typeof val === "object") {
553:       collectObjectStrings(val as Record<string, unknown>, field, result);
554:     }
555:   };
556: 
557:   const modes = typeof node.do === "string" ? NODE_FIELD_MODES[node.do] : undefined;
558:   if (modes) {
559:     for (const [field, mode] of Object.entries(modes)) {
560:       if (mode === "template" || mode === "templateEach" || mode === "templateDeep") {
561:         scan(field, raw[field]);
562:       }
563:     }
564:   } else {
565:     // Custom-step node: every declared field is treated as potentially template-bearing.
566:     const customStep = typeof node.do === "string" ? registry.get(node.do) : undefined;
567:     if (customStep) {
568:       for (const field of customStep.allowedKeys) scan(field, raw[field]);
569:     }
570:   }
571: 
572:   return result;
573: }
