39:   context?: {
40:     sessionKey?: string;
41:     sessionId?: string;
42:     agentId?: string;
43:     runId?: string;
44:     [k: string]: unknown;
45:   };
46:   [k: string]: unknown;
47: }
48: 
49: type RequireApprovalDecision = {
50:   title: string;
51:   description: string;
52:   severity?: "info" | "warning" | "critical";
53:   timeoutMs?: number;
54:   timeoutBehavior?: "allow" | "deny";
55: };
56: 
57: interface PluginApi {
58:   registerTool: (def: object, opts?: { optional?: boolean }) => void;
59:   registerHook?: (
60:     events: string | string[],
61:     handler: (event: BeforeToolCallEvent) =>
62:       | { requireApproval?: RequireApprovalDecision; block?: boolean; blockReason?: string }
63:       | void
64:       | Promise<{ requireApproval?: RequireApprovalDecision; block?: boolean; blockReason?: string } | void>,
65:     opts: { name: string; description?: string; priority?: number },
66:   ) => void;
67:   config?: {
68:     plugins?: { entries?: Record<string, { config?: PluginConfig }> };
69:     gateway?: { port?: number; host?: string };
70:     [key: string]: unknown;
71:   };
72:   runtime?: {
73:     config?: { loadConfig?: () => unknown };
74:     [key: string]: unknown;
75:   };
76:   logger?: {
77:     info: (msg: string) => void;
78:     warn: (msg: string) => void;
79:     error: (msg: string) => void;
80:   };
81: }
82: 
83: function register(api: PluginApi) {
84:   const rawCfg: PluginConfig =
85:     api.config?.plugins?.entries?.["clawflow"]?.config ?? {};
86: 
87:   const pluginCfg: PluginConfig = { ...rawCfg };
88: 
89:   // Resolve workspace root once at registration time.
90:   // Try: env var → api.config.workspace → OpenClaw default → cwd()
91:   const workspace: string =
92:     process.env.OPENCLAW_WORKSPACE ??
93:     (api.config as Record<string, unknown> | undefined)?.workspace as string ??
94:     (process.env.HOME ? `${process.env.HOME}/.openclaw/workspace` : null) ??
95:     process.cwd();
96: 
97:   api.logger?.info(`clawflow workspace: ${workspace}`);
98: 
99:   const runner = new FlowRunner(pluginCfg);
100:   const store = runner.getStore();
101: 
102:   // ---- Flow server (optional) ---------------------------------------------------
103:   // Skip when spawned as a child agent (CLAWFLOW_NO_SERVE) to avoid port conflicts.
104:   if (pluginCfg.serve && !process.env.CLAWFLOW_NO_SERVE) {
105:     startFlowServer({
106:       runner,
107:       serve: pluginCfg.serve,
108:       // Same workspace the flow_* tools use, so a triggered run resolves the
109:       // published version exactly like flow_run does.
110:       workspace,
111:       logger: api.logger,
112:     });
113:   }
114: 
115:   // ---- Trigger scheduler --------------------------------------------------------
116:   // Fires scheduled flows on this box. Skipped for child agents alongside the
117:   // flow server so a spawned agent never double-fires its parent's triggers.
118:   const flowsDir = pluginCfg.serve?.flowsDir ?? path.join(workspace, "flows");
119:   const triggerStore = new TriggerStore(workspace);
120:   const scheduler = new TriggerScheduler({
121:     runner,
122:     store: triggerStore,
123:     workspace,
124:     flowsDir,
125:     logger: api.logger,
126:   });
127:   if (!process.env.CLAWFLOW_NO_SERVE) {
128:     scheduler.start();
129:   }
130: 
131:   // ---- Approval gate for flow_run -----------------------------------------------
132:   // Flows can call HTTP, exec, and agent tools, so by default we prompt the user
133:   // before each run. Disable entirely (`approval.enabled: false`) or skip for
134:   // specific session contexts (`approval.skipSessionPatterns`) — useful for
135:   // hook-driven, unattended automation that has no interactive channel to
136:   // approve in.
137:   const approvalCfg = pluginCfg.approval ?? {};
138:   const approvalEnabled = approvalCfg.enabled !== false;
139:   const skipPatterns = Array.isArray(approvalCfg.skipSessionPatterns)
140:     ? approvalCfg.skipSessionPatterns.filter((p): p is string => typeof p === "string" && p.length > 0)
141:     : [];
142:   const approvalTimeoutMs =
143:     typeof approvalCfg.timeoutMs === "number" && approvalCfg.timeoutMs > 0
144:       ? approvalCfg.timeoutMs
145:       : 5 * 60_000;
146:   const approvalTimeoutBehavior: "allow" | "deny" =
147:     approvalCfg.timeoutBehavior === "allow" ? "allow" : "deny";
148:   // Intrinsic mutation gate: authoring/publishing/deleting a flow is a write
149:   // action that must never run without a human OK, so it is gated on every call
150:   // independently of `enabled` (which governs flow_run) and does NOT honor
151:   // skipSessionPatterns. Kill-switch: approval.gateMutations=false.
152:   const gateMutations = approvalCfg.gateMutations !== false;
153:   // Arming a schedule commits the box to running a flow unattended, on a timer,
154:   // with tool access — at least as consequential as editing one, so it is gated
155:   // the same way. Reads (list) are not gated.
156:   const TRIGGER_MUTATION_VERBS: Record<string, string> = {
157:     create: "Schedule",
158:     update: "Reschedule",
159:     delete: "Unschedule",
160:     pause: "Pause schedule for",
161:     resume: "Resume schedule for",
162:     run_now: "Run now",
163:   };
164: 
165:   const MUTATION_VERBS: Record<string, string> = {
166:     flow_create: "Create",
167:     flow_edit: "Edit",
168:     flow_publish: "Publish",
169:     flow_delete: "Delete",
170:   };
171: 
172:   if (api.registerHook && (approvalEnabled || gateMutations)) {
173:     api.registerHook(
174:       "before_tool_call",
175:       (event) => {
176:         const toolName = event.toolName ?? event.tool;
177: 
178:         // Flow-authoring tools — always gate (no skipSessionPatterns). No
179:         // allow-always persist path, so every call re-prompts.
180:         // flow_trigger is action-shaped: gate the mutating actions, let reads through.
181:         let mutationVerb = toolName ? MUTATION_VERBS[toolName] : undefined;
182:         if (toolName === "flow_trigger") {
183:           const action = (event.params as { action?: string } | undefined)?.action;
184:           mutationVerb = TRIGGER_MUTATION_VERBS[action ?? ""] ?? undefined;
185:         }
186:         if (gateMutations && mutationVerb) {
187:           const mp = (event.params ?? {}) as { file?: string; flow?: string; id?: string };
188:           const name = mp.flow ?? mp.file ?? mp.id ?? "inline flow";
189:           return {
190:             requireApproval: {
191:               title: `${mutationVerb} clawflow "${name}"?`.slice(0, 80),
192:               description:
193:                 toolName === "flow_trigger"
194:                   ? "Changes an unattended schedule that runs a flow on a timer."
195:                   : "Creates, edits, publishes, or deletes a flow definition.",
196:               severity: "warning",
197:               timeoutMs: approvalTimeoutMs,
198:               timeoutBehavior: approvalTimeoutBehavior,
199:             },
200:           };
201:         }
202: 
203:         if (!approvalEnabled || toolName !== "flow_run") return;
204: 
205:         const sessionKey = event.context?.sessionKey ?? "";
206:         if (skipPatterns.some((pattern) => sessionKey.includes(pattern))) {
207:           return;
208:         }
209: 
210:         const p = (event.params ?? {}) as { file?: string; flow?: { flow?: string }; version?: number; draft?: boolean };
211:         const target = p.file ?? p.flow?.flow ?? "inline flow";
212:         const variant =
213:           p.version != null ? ` v${p.version}` : p.draft ? " (draft)" : "";
214:         return {
215:           requireApproval: {
216:             title: `Run clawflow "${target}"${variant}?`,
217:             description: "Flows may call HTTP, exec, and agent tools.",
218:             severity: "warning",
219:             timeoutMs: approvalTimeoutMs,
220:             timeoutBehavior: approvalTimeoutBehavior,
221:           },
222:         };
223:       },
224:       {
225:         name: "clawflow-approval-gate",
226:         description: "Gate flow_run (skippable) and flow authoring/publishing/deletion (always) behind user approval.",
227:       },
228:     );
229:   } else if (!api.registerHook) {
230:     api.logger?.warn(
231:       "clawflow: registerHook unavailable — flow_run will run without approval gate. Update OpenClaw to enable.",
232:     );
233:   }
234: 
235:   // ---- Shared helpers ------------------------------------------------------------
236:   // Draft/version semantics live in core/manage.ts (engine-owned, shared with
237:   // out-of-process callers); these closures just bind the plugin's workspace.
238: 
239:   /** Resolve a file param to an absolute path using workspace conventions. */
240:   function resolveFlowFile(file: string): string {
241:     return resolveFlowFileCore(workspace, file);
242:   }
243: 
244:   /** List all published version numbers for a flow, sorted ascending. */
245:   function listVersions(flowName: string): number[] {
246:     return listVersionsCore(workspace, flowName);
247:   }
248: 
249:   /** Read a specific published version. Returns null if not found. */
250:   function readVersion(flowName: string, version: number): FlowDefinition | null {
251:     return readVersionCore(workspace, flowName, version);
252:   }
253: 
254:   /** Get the latest published version definition. Returns null if none published. */
255:   function readLatestVersion(flowName: string): { version: number; def: FlowDefinition } | null {
256:     return readLatestVersionCore(workspace, flowName);
257:   }
258: 
259:   // ---- flow_create --------------------------------------------------------------
260: 
261:   api.registerTool(
262:     {
263:       name: "flow_create",
264:       description: `Create a new clawflow definition and save it to a JSON file.
265: 
266: Builds a FlowDefinition from the provided parameters, validates it, and writes
267: it to disk. Use this to scaffold a new flow file; use flow_edit to modify it
268: afterwards and flow_run to execute it.
269: 
270: Node types:
271:   ai, agent, branch, condition, loop, parallel, http, memory, wait, sleep, code, exec
272: 
273: All nodes require "name" and "do". Templates: {{ outputKey.field }}.`,
274: 
275:       parameters: {
276:         type: "object",
277:         required: ["file", "flow", "nodes"],
278:         properties: {
279:           file: {
280:             type: "string",
281:             description:
282:               "Filename or path for the new flow file. Plain names like \"my-flow\" are saved to workspace/flows/my-flow.json. Paths with slashes are resolved relative to the workspace.",
283:           },
284:           flow: {
285:             type: "string",
286:             description: "Unique flow name",
287:           },
288:           description: {
289:             type: "string",
290:             description: "Human-readable description of what the flow does",
291:           },
292:           nodes: {
293:             type: "array",
294:             items: { type: "object", additionalProperties: true },
295:             description: "Array of node definitions",
296:           },
297:           inputs: {
298:             type: "object",
299:             additionalProperties: true,
300:             description:
301:               'Declared inputs the flow expects. Map of name → { type?, required?, description?, default? }. Optional: when omitted, the flow accepts any payload. When present, required inputs are enforced before any node runs.',
302:           },
303:           env: {
304:             type: "object",
305:             additionalProperties: true,
306:             description: "Environment variable defaults",
307:           },
308:           version: {
309:             type: "string",
310:             description: 'Semver version string, e.g. "1.0.0"',
311:           },
312:         },
313:       },
314: 
315:       async execute(
316:         _id: string,
317:         params: {
318:           file: string;
319:           flow: string;
320:           description?: string;
321:           nodes: FlowNode[];
322:           inputs?: FlowDefinition["inputs"];
323:           env?: Record<string, string | null>;
324:           version?: string;
325:         },
326:       ) {
327:         const fs = await import("fs");
328:         const path = await import("path");
329: 
330:         const base = workspace;
331: 
332:         let abs: string;
333:         if (params.file.startsWith("/")) {
334:           abs = params.file;
335:         } else if (params.file.includes("/")) {
336:           // Relative path with directory — resolve from workspace root
337:           abs = path.join(base, params.file);
338:         } else {
339:           // Plain name — put in workspace/flows/
340:           const name = params.file.replace(/\.json$/, "");
341:           abs = path.join(base, "flows", `${name}.json`);
342:         }
343: 
344:         if (fs.existsSync(abs))
345:           return {
346:             content: [
347:               {
348:                 type: "text",
349:                 text: `File already exists: ${abs}. Use flow_edit to modify it.`,
350:               },
351:             ],
352:           };
353: 
354:         const flowDef: FlowDefinition = {
355:           flow: params.flow,
356:           ...(params.version && { version: params.version }),
357:           ...(params.description && { description: params.description }),
358:           ...(params.inputs && { inputs: params.inputs }),
359:           ...(params.env && { env: params.env }),
360:           nodes: params.nodes,
361:         };
362: 
363:         const validation = validateFlow(flowDef);
364:         if (!validation.ok)
365:           return {
366:             content: [
367:               {
368:                 type: "text",
369:                 text: `Validation failed:\n${validation.errors.map((e) => `  - ${e.message}`).join("\n")}`,
370:               },
371:             ],
372:           };
373: 
374:         try {
375:           fs.mkdirSync(path.dirname(abs), { recursive: true });
376:         } catch (err) {
377:           const msg = err instanceof Error ? err.message : String(err);
378:           return {
379:             content: [
380:               {
381:                 type: "text",
382:                 text: `Cannot create directory for ${abs}: ${msg}. Is OPENCLAW_WORKSPACE set? Current workspace root: ${base}`,
383:               },
384:             ],
385:           };
386:         }
387:         fs.writeFileSync(abs, JSON.stringify(flowDef, null, 2) + "\n");
388: 
389:         return {
390:           content: [
391:             {
392:               type: "text",
393:               text: `Flow "${params.flow}" created at ${abs}`,
394:             },
395:           ],
396:           details: flowDef,
397:         };
398:       },
399:     },
400:     { optional: true },
401:   );
402: 
403:   // ---- flow_delete --------------------------------------------------------------
404: 
405:   api.registerTool(
406:     {
407:       name: "flow_delete",
408:       description: `Delete a flow file by moving it to the bin.
409: 
410: The flow is not permanently removed — it is timestamped and moved to
411: workspace/.clawflow/bin/ so it can be restored later with flow_restore_from_bin.
412: Safe for agents to call without fear of data loss.`,
413: 
414:       parameters: {
415:         type: "object",
416:         required: ["file"],
417:         properties: {
418:           file: {
419:             type: "string",
420:             description:
421:               "Filename or path of the flow to delete. Plain names like \"my-flow\" resolve to workspace/flows/my-flow.json.",
422:           },
423:         },
424:       },
425: 
426:       async execute(
427:         _id: string,
428:         params: { file: string },
429:       ) {
430:         const fs = await import("fs");
431:         const path = await import("path");
432: 
433:         const base = workspace;
434: 
435:         let abs: string;
436:         if (params.file.startsWith("/")) {
437:           abs = params.file;
438:         } else if (params.file.includes("/")) {
439:           abs = path.join(base, params.file);
440:         } else {
441:           const name = params.file.replace(/\.json$/, "");
442:           abs = path.join(base, "flows", `${name}.json`);
443:         }
444: 
445:         if (!fs.existsSync(abs))
446:           return {
447:             content: [{ type: "text", text: `File not found: ${abs}` }],
448:           };
449: 
450:         const binDir = path.join(base, ".clawflow", "bin");
451:         fs.mkdirSync(binDir, { recursive: true });
452: 
453:         const basename = path.basename(abs, ".json");
454:         const ts = new Date().toISOString().replace(/[:.]/g, "-");
455:         const binPath = path.join(binDir, `${basename}.${ts}.json`);
456: 
457:         fs.renameSync(abs, binPath);
458: 
459:         // Schedules outlive a soft delete, but must not keep firing at a flow
460:         // that is no longer there. Paused, not removed, so a restore keeps them.
461:         const pausedIds = triggerStore.pauseForFlow(path.basename(abs, ".json"));
462:         const pausedNote =
463:           pausedIds.length > 0
464:             ? `\nPaused ${pausedIds.length} trigger(s) for this flow: ${pausedIds.join(", ")}`
465:             : "";
466: 
467:         return {
468:           content: [
469:             {
470:               type: "text",
471:               text: `Flow moved to bin: ${binPath}${pausedNote}`,
472:             },
473:           ],
474:         };
475:       },
476:     },
477:     { optional: true },
478:   );
479: 
480:   // ---- flow_restore_from_bin -------------------------------------------------------------
481: 
482:   api.registerTool(
483:     {
484:       name: "flow_restore_from_bin",
485:       description: `Restore a flow from the bin or list bin contents.
486: 
487: Without "name", lists all flows in workspace/.clawflow/bin/ with their timestamps.
488: With "name", restores the most recent version of that flow back to the flows/
489: directory. If the flow file already exists, the restore is rejected.`,
490: 
491:       parameters: {
492:         type: "object",
493:         properties: {
494:           name: {
495:             type: "string",
496:             description:
497:               "Flow name to restore (without timestamp). Omit to list all bin contents.",
498:           },
499:         },
500:       },
501: 
502:       async execute(
503:         _id: string,
504:         params: { name?: string },
505:       ) {
506:         const fs = await import("fs");
507:         const path = await import("path");
508: 
509:         const base = workspace;
510:         const binDir = path.join(base, ".clawflow", "bin");
511: 
512:         if (!fs.existsSync(binDir))
513:           return {
514:             content: [{ type: "text", text: "Bin is empty." }],
515:           };
516: 
517:         const files = fs.readdirSync(binDir)
518:           .filter((f: string) => f.endsWith(".json"))
519:           .sort()
520:           .reverse();
521: 
522:         if (files.length === 0)
523:           return {
524:             content: [{ type: "text", text: "Bin is empty." }],
525:           };
526: 
527:         // ---- List mode ---
528:         if (!params.name) {
529:           const entries = files.map((f: string) => {
530:             const match = f.match(/^(.+?)\.(\d{4}-.+)\.json$/);
531:             return {
532:               name: match?.[1] ?? f,
533:               deletedAt: match?.[2] ?? "unknown",
534:               file: f,
535:             };
536:           });
537:           return {
538:             content: [
539:               { type: "text", text: JSON.stringify(entries, null, 2) },
540:             ],
541:             details: entries,
542:           };
543:         }
544: 
545:         // ---- Restore mode ---
546:         const prefix = params.name.replace(/\.json$/, "");
547:         const match = files.find((f: string) => f.startsWith(`${prefix}.`));
548: 
549:         if (!match)
550:           return {
551:             content: [
552:               {
553:                 type: "text",
554:                 text: `No bin entry found for "${prefix}".`,
555:               },
556:             ],
557:           };
558: 
559:         const dest = path.join(base, "flows", `${prefix}.json`);
560:         if (fs.existsSync(dest))
561:           return {
562:             content: [
563:               {
564:                 type: "text",
565:                 text: `Cannot restore: ${dest} already exists. Delete or rename it first.`,
566:               },
567:             ],
568:           };
569: 
570:         fs.renameSync(path.join(binDir, match), dest);
571: 
572:         return {
573:           content: [
574:             {
575:               type: "text",
576:               text: `Restored "${prefix}" from bin to ${dest}`,
577:             },
578:           ],
579:         };
580:       },
581:     },
582:     { optional: true },
583:   );
584: 
585:   // ---- flow_run -----------------------------------------------------------------
586: 
587:   api.registerTool(
588:     {
589:       name: "flow_run",
590:       catalogMode: "direct-only",
591:       description: `Run an agentic workflow in the clawflow format.
592: 
593: State model:
594:   The "input" parameter becomes "inputs" in flow state (i.e. state.inputs).
595:   Flow state = { inputs, env?, ...nodeOutputs }.
596:   Each node with "output" adds its result to state (e.g. output: "result" → state.result).
597:   In code nodes: fn(input, state) — "input" is the resolved node.input field, "state" is the full flow state.
598:   IMPORTANT: inputs contains ALL initial data. If you need different parts of inputs in a code node,
599:   use object-style input: { "payload": "inputs.payload", "email": "inputs.email_to" }
600:   or access via state.inputs.field inside the code.
601: 
602: Node types:
603:   ai       — LLM call, structured or freeform. Use schema: for typed output.
604:   agent    — delegate to a real OpenClaw agent. Fields mirror the CLI flags: agent
605:              (a configured slug, e.g. "clawflow" → --agent), sessionKey (a session
606:              key, e.g. "agent:main:slack:channel:agent" → --session-key), sessionId
607:              (→ --session-id), channel (→ --channel). A bare session key is scoped by
608:              agent; an "agent:"-prefixed key is self-scoping. (agentId/session are
609:              deprecated aliases for agent/sessionKey.)
610:   branch   — route to different nodes based on a value: { on, paths, default }
611:   loop     — iterate over a list: { over, as, nodes[] }
612:   parallel — run nodes concurrently: { nodes[], mode: "all"|"race" }
613:   http     — call an external API: { url, method, body, headers }
614:   memory   — persist data: { action: read|write|delete, key, value }
615:   wait     — pause for approval or event: { for: "approval"|"event", event?, timeout? }
616:   sleep    — pause for duration: { duration: "5m" }
617:   code     — inline JS expression: { run: "...", input? }
618: 
619: All nodes support retry: { limit, delay, backoff } and timeout.
620: Templates: use {{ nodeName.field }} to reference any value in flow state.
621: Returns instanceId for status tracking and resume.
622: 
623: Versioning: when a flow has published versions, flow_run uses the latest
624: published version by default. Set draft: true to run the working copy instead.
625: Set version to run a specific published version.`,
626: 
627:       parameters: {
628:         type: "object",
629:         properties: {
630:           flow: {
631:             type: "object",
632:             properties: {
633:               flow: { type: "string" },
634:               description: { type: "string" },
635:               nodes: {
636:                 type: "array",
637:                 items: { type: "object", additionalProperties: true },
638:               },
639:             },
640:             required: ["flow", "nodes"],
641:             additionalProperties: true,
642:           },
643:           file: {
644:             type: "string",
645:             description: "Path to a .json flow file (or plain name like \"my-flow\")",
646:           },
647:           input: {
648:             type: "object",
649:             additionalProperties: true,
650:             description: "Input data, available as inputs.* in the flow (and at state.inputs in code nodes).",
651:           },
652:           draft: {
653:             type: "boolean",
654:             description:
655:               "Run the draft (working copy) instead of the latest published version. Default: false.",
656:           },
657:           version: {
658:             type: "number",
659:             description:
660:               "Run a specific published version number. Overrides draft flag.",
661:           },
662:         },
663:       },
664: 
665:       async execute(
666:         _id: string,
667:         params: {
668:           flow?: FlowDefinition;
669:           file?: string;
670:           input?: unknown;
671:           draft?: boolean;
672:           version?: number;
673:         },
674:       ) {
675:         let flowDef: FlowDefinition;
676:         let source = "";
677: 
678:         if (params.file) {
679:           const { readFileSync, existsSync } = await import("fs");
680:           const pathMod = await import("path");
681:           const abs = resolveFlowFile(params.file);
682: 
683:           // Determine flow name for version lookup
684:           const flowName = pathMod.basename(abs, ".json");
685: 
686:           if (params.version != null) {
687:             // Specific version requested
688:             const vDef = readVersion(flowName, params.version);
689:             if (!vDef)
690:               return {
691:                 content: [
