58: /** BFS depth from the trigger (roots when no trigger exists). */
59: function depths(nodes: GraphNode[], edges: GraphEdge[]): Map<string, number> {
60:   const incoming = new Map<string, string[]>();
61:   for (const e of edges) {
62:     incoming.set(e.targetKey, [...(incoming.get(e.targetKey) ?? []), e.sourceKey]);
63:   }
64:   const depth = new Map<string, number>();
65:   const queue: string[] = [];
66:   for (const n of nodes) {
67:     if (!incoming.get(n.nodeKey)?.length) {
68:       depth.set(n.nodeKey, 0);
69:       queue.push(n.nodeKey);
70:     }
71:   }
72:   let head = 0;
73:   while (head < queue.length) {
74:     const cur = queue[head++];
75:     const d = depth.get(cur)!;
76:     for (const e of edges) {
77:       if (e.sourceKey === cur && !depth.has(e.targetKey)) {
78:         depth.set(e.targetKey, d + 1);
79:         queue.push(e.targetKey);
80:       }
81:     }
82:   }
83:   for (const n of nodes) {
84:     if (!depth.has(n.nodeKey)) depth.set(n.nodeKey, 0);
85:   }
86:   return depth;
87: }
88: 
89: export function toFlow(graph: WorkflowGraph): { nodes: FlowNode[]; edges: FlowEdge[] } {
90:   const depth = depths(graph.nodes, graph.edges);
91:   const perColumn = new Map<number, number>();
92:   const nodes = graph.nodes.map((n) => {
93:     const col = depth.get(n.nodeKey)!;
94:     const row = perColumn.get(col) ?? 0;
95:     perColumn.set(col, row + 1);
96:     return {
97:       id: n.nodeKey,
98:       type: "workflow",
99:       position: {
100:         x: n.positionX || col * COL_WIDTH,
101:         y: n.positionY || row * ROW_HEIGHT,
102:       },
103:       data: { graphNode: n },
104:     };
105:   });
106:   const edges = graph.edges.map((e) => ({
107:     id: `${e.sourceKey}${e.handle ? `[${e.handle}]` : ""}->${e.targetKey}`,
108:     source: e.sourceKey,
109:     target: e.targetKey,
110:     sourceHandle: e.handle ?? null,
111:   }));
112:   return { nodes, edges };
113: }
